import type { FC } from "react";

export function CalculatorWidget(): JSX.Element {
  const [display, setDisplay] = React.useState<string>("0");

  const handleClick = (value: string): void => {
    if (value === "C") {
      setDisplay("0");
    } else if (value === "=") {
      try {
        setDisplay(eval(display).toString());
      } catch (
        e: unknown
      ) {
        setDisplay("Error");
      }
    } else {
      setDisplay(prevDisplay => prevDisplay === "0" ? value : prevDisplay + value);
    }
  };

  return (
    <div style={{ display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", height: "100vh" }}>
      <input type="text" value={display} readOnly style={{ width: "200px", fontSize: "24px", textAlign: "right" }} />
      <div style={{ display: "grid", gridTemplateRows: "repeat(4, 1fr)", gridTemplateColumns: "repeat(4, 1fr)", gap: "10px" }}>
        <button onClick={() => handleClick("C")}>C</button>
        <button onClick={() => handleClick("/")}>/</button>
        <button onClick={() => handleClick("*")}>*</button>
        <button onClick={() => handleClick("-")}>-</button>
        <button onClick={() => handleClick("7")}>7</button>
        <button onClick={() => handleClick("8")}>8</button>
        <button onClick={() => handleClick("9")}>9</button>
        <button onClick={() => handleClick("+")}>+</button>
        <button onClick={() => handleClick("4")}>4</button>
        <button onClick={() => handleClick("5")}>5</button>
        <button onClick={() => handleClick("6")}>6</button>
        <button onClick={() => handleClick(".")}>.</button>
        <button onClick={() => handleClick("1")}>1</button>
        <button onClick={() => handleClick("2")}>2</button>
        <button onClick={() => handleClick("3")}>3</button>
        <button onClick={() => handleClick("=")}>=</button>
      </div>
    </div>
  );
}

import { DatabaseSync } from "node:sqlite";

export interface Product {
  id: number;
  name: string;
  price: number;
  stockCount: number;
}

export const db = new DatabaseSync(":memory:");
db.exec(`
  CREATE TABLE IF NOT EXISTS products (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    price REAL NOT NULL,
    stockCount INTEGER NOT NULL
  );
`);

export function insertProduct(name: string, price: number, stockCount: number): void {
  db.prepare(`INSERT INTO products (name, price, stockCount) VALUES (?, ?, ?)`).run(name, price, stockCount);
}

export function getProductById(id: number): Product | undefined {
  const stmt = db.prepare(`SELECT * FROM products WHERE id = ?`).get(id);
  return stmt as unknown as Product;
}

export function getAllProducts(): Product[] {
  const stmt = db.prepare(`SELECT * FROM products`).all();
  return stmt as unknown as Product[];
}

export function updateProductStock(id: number, stockCount: number): void {
  db.prepare(`UPDATE products SET stockCount = ? WHERE id = ?`).run(stockCount, id);
}

export function deleteProduct(id: number): void {
  db.prepare(`DELETE FROM products WHERE id = ?`).run(id);
}

