export interface Order {
  orderId: number;
  customerId: number;
  lineItems: string;
  paymentStatus: string;
}

export const db = new DatabaseSync(":memory:");
db.exec(`
  CREATE TABLE IF NOT EXISTS orders (
    orderId INTEGER PRIMARY KEY AUTOINCREMENT,
    customerId INTEGER NOT NULL,
    lineItems TEXT NOT NULL,
    paymentStatus TEXT NOT NULL
  );
`);

export function insertOrder(order: Omit<Order, 'orderId'>): void {
  const stmt = db.prepare(`INSERT INTO orders (customerId, lineItems, paymentStatus) VALUES (?, ?, ?)`);
  stmt.run(order.customerId, order.lineItems, order.paymentStatus);
}

export function getOrderById(orderId: number): Order | undefined {
  const stmt = db.prepare(`SELECT * FROM orders WHERE orderId = ?`);
  const result = stmt.get(orderId) as unknown as Order;
  return result;
}

export function getAllOrders(): Order[] {
  const stmt = db.prepare(`SELECT * FROM orders`);
  const results = stmt.all() as unknown as Order[];
  return results;
}

