import React, { useState, useEffect } from "react";

interface Product {
  id: number;
  name: string;
  description: string;
  price: number;
}

export function AdminProductPanel(): JSX.Element {
  const [products, setProducts] = useState<Product[]>([]);
  const [newProductName, setNewProductName] = useState<string>("");
  const [newProductDescription, setNewProductDescription] = useState<string>("");
  const [newProductPrice, setNewProductPrice] = useState<number>(0);

  useEffect(() => {
    fetch("/api/catalog-api/")
      .then(response => response.json())
      .then(data => setProducts(data));
  }, []);

  const handleAddProduct = async () => {
    const product = {
      name: newProductName,
      description: newProductDescription,
      price: newProductPrice,
    };
    const response = await fetch("/api/catalog-api/", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify(product),
    });
    if (response.ok) {
      setProducts([...products, product]);
      setNewProductName("");
      setNewProductDescription("");
      setNewProductPrice(0);
    }
  };

  const handleEditProduct = async (id: number, updatedProduct: Partial<Product>) => {
    const response = await fetch(`/api/catalog-api/${id}`, {
      method: "PUT",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify(updatedProduct),
    });
    if (response.ok) {
      setProducts(products.map(p => p.id === id ? { ...p, ...updatedProduct } : p));
    }
  };

  const handleDeleteProduct = async (id: number) => {
    const response = await fetch(`/api/catalog-api/${id}`, {
      method: "DELETE",
    });
    if (response.ok) {
      setProducts(products.filter(p => p.id !== id));
    }
  };

  return (
    <div>
      <h1>Admin Product Panel</h1>
      <div>
        <input
          type="text"
          placeholder="Name"
          value={newProductName}
          onChange={(e) => setNewProductName(e.target.value)}
        />
        <input
          type="text"
          placeholder="Description"
          value={newProductDescription}
          onChange={(e) => setNewProductDescription(e.target.value)}
        />
        <input
          type="number"
          placeholder="Price"
          value={newProductPrice}
          onChange={(e) => setNewProductPrice(Number(e.target.value))}
        />
        <button onClick={handleAddProduct}>Add Product</button>
      </div>
      <ul>
        {products.map(product => (
          <li key={product.id}>
            {product.name} - {product.description} - ${product.price.toFixed(2)}
            <button onClick={() => handleEditProduct(product.id, { name: "Updated Name" })}>Edit</button>
            <button onClick={() => handleDeleteProduct(product.id)}>Delete</button>
          </li>
        ))}
      </ul>
    </div>
  );
}

