import React, { FC, useState } from "react";

interface Customer {
  id: number;
  email: string;
  accountId: string;
}

export function CustomerLookup(): JSX.Element {
  const [searchTerm, setSearchTerm] = useState<string>("");
  const [customer, setCustomer] = useState<Customer | null>(null);

  const handleSearch = async (): Promise<void> => {
    try {
      const response = await fetch(`/api/customer-lookup-api/customer-lookup/${encodeURIComponent(searchTerm)}`);
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      setCustomer(data);
    } catch (error) {
      console.error("Error fetching customer:", error);
    }
  };

  return (
    <div>
      <input
        type="text"
        placeholder="Enter email or account ID"
        value={searchTerm}
        onChange={(e) => setSearchTerm(e.target.value)}
      />
      <button onClick={handleSearch}>Search</button>
      {customer && (
        <div>
          <p>ID: {customer.id}</p>
          <p>Email: {customer.email}</p>
          <p>Account ID: {customer.accountId}</p>
        </div>
      )}
    </div>
  );
}

import React, { FC, useState } from "react";

interface RefundFormData {
  customerId: string;
  amount: number;
  reasonCode: string;
}

export function RefundPanel(): JSX.Element {
  const [formData, setFormData] = useState<Partial<RefundFormData>>({
    customerId: "",
    amount: 0,
    reasonCode: "",
  });

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>): void => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: name === "amount" ? Number(value) : value });
  };

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>): Promise<void> => {
    e.preventDefault();
    try {
      const response = await fetch("/api/refund-api/refund", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(formData),
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      alert("Refund issued successfully!");
    } catch (error) {
      console.error("Error issuing refund:", error);
      alert("Failed to issue refund.");
    }
  };

  return (
    <div>
      <h1>Issue Refund</h1>
      <form onSubmit={handleSubmit}>
        <label htmlFor="customerId">Customer ID:</label>
        <input
          type="text"
          id="customerId"
          name="customerId"
          value={formData.customerId}
          onChange={handleChange}
          required
        />

        <label htmlFor="amount">Amount:</label>
        <input
          type="number"
          id="amount"
          name="amount"
          value={formData.amount}
          onChange={handleChange}
          step="0.01"
          required
        />

        <label htmlFor="reasonCode">Reason Code:</label>
        <input
          type="text"
          id="reasonCode"
          name="reasonCode"
          value={formData.reasonCode}
          onChange={handleChange}
          required
        />

        <button type="submit">Submit</button>
      </form>
    </div>
  );
}

