import React, { FC, useState, useEffect } from "react";

interface Book {
  id: number;
  title: string;
  author: string;
}

export function StaffInventoryPanel(): JSX.Element {
  const [books, setBooks] = useState<Book[]>([]);

  useEffect(() => {
    fetch("/api/catalogue-api/books")
      .then(response => response.json())
      .then(data => setBooks(data));
  }, []);

  const handleAddBook = async (title: string, author: string) => {
    const newBook = { title, author };
    const response = await fetch("/api/catalogue-api/books", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(newBook),
    });
    if (response.ok) {
      setBooks([...books, await response.json()]);
    }
  };

  const handleRemoveBook = async (id: number) => {
    await fetch(`/api/catalogue-api/books/${id}`, { method: "DELETE" });
    setBooks(books.filter(book => book.id !== id));
  };

  const handleUpdateBook = async (id: number, title: string, author: string) => {
    const updatedBook = { title, author };
    const response = await fetch(`/api/catalogue-api/books/${id}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(updatedBook),
    });
    if (response.ok) {
      setBooks(books.map(book => book.id === id ? { ...book, ...updatedBook } : book));
    }
  };

  return (
    <div>
      <h1>Staff Inventory Panel</h1>
      <button onClick={() => handleAddBook("New Book Title", "Author Name")}>Add Book</button>
      <ul>
        {books.map(book => (
          <li key={book.id}>
            {book.title} by {book.author}
            <button onClick={() => handleRemoveBook(book.id)}>Remove</button>
            <button onClick={() => handleUpdateBook(book.id, "Updated Title", "Updated Author")}>Update</button>
          </li>
        ))}
      </ul>
    </div>
  );
}

