  option1: string;
  option2: string;
  option3: string;
  option4: string;
  votesForOption1: number;
  votesForOption2: number;
  votesForOption3: number;
  votesForOption4: number;
}

export const db = new DatabaseSync(":memory:");
db.exec(`
  CREATE TABLE IF NOT EXISTS polls (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    question TEXT NOT NULL,
    option1 TEXT NOT NULL,
    option2 TEXT NOT NULL,
    option3 TEXT,
    option4 TEXT,
    votesForOption1 INTEGER DEFAULT 0,
    votesForOption2 INTEGER DEFAULT 0,
    votesForOption3 INTEGER DEFAULT 0,
    votesForOption4 INTEGER DEFAULT 0
  );
`);

export function createPoll(question: string, option1: string, option2: string, option3?: string, option4?: string): void {
  const stmt = db.prepare(`
    INSERT INTO polls (question, option1, option2, option3, option4)
    VALUES (?, ?, ?, ?, ?)
  `);
  stmt.run(question, option1, option2, option3 ?? null, option4 ?? null);
}

export function getPollById(id: number): Poll | undefined {
  const stmt = db.prepare(`SELECT * FROM polls WHERE id = ?`);
  const result = stmt.get(id) as unknown as Poll;
  return result;
}

export function voteForOption(pollId: number, optionIndex: number): void {
  let stmt;
  switch (optionIndex) {
    case 1:
      stmt = db.prepare(`UPDATE polls SET votesForOption1 = votesForOption1 + 1 WHERE id = ?`);
      break;
    case 2:
      stmt = db.prepare(`UPDATE polls SET votesForOption2 = votesForOption2 + 1 WHERE id = ?`);
      break;
    case 3:
      stmt = db.prepare(`UPDATE polls SET votesForOption3 = votesForOption3 + 1 WHERE id = ?`);
      break;
    case 4:
      stmt = db.prepare(`UPDATE polls SET votesForOption4 = votesForOption4 + 1 WHERE id = ?`);
      break;
    default:
      throw new Error(`Invalid option index: ${optionIndex}`);
  }
  stmt.run(pollId);
}

