  const [question, setQuestion] = useState<string>("");
  const [options, setOptions] = useState<Option[]>([]);
  const [newOptionText, setNewOptionText] = useState<string>("");

  const handleAddOption = (): void => {
    if (newOptionText.trim()) {
      setOptions([...options, { id: Date.now(), text: newOptionText.trim() }]);
      setNewOptionText("");
    }
  };

  const handleSubmit = async (event: React.FormEvent<HTMLFormElement>): Promise<void> => {
    event.preventDefault();
    const response = await fetch("/api/polls-api/", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ question, options: options.map(option => option.text) }),
    });
    if (!response.ok) {
      console.error("Failed to create poll");
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <div>
        <label htmlFor="question">Question:</label>
        <input
          type="text"
          id="question"
          value={question}
          onChange={(e) => setQuestion(e.target.value)}
          required
        />
      </div>
      <div>
        <h3>Options:</h3>
        <ul>
          {options.map((option) => (
            <li key={option.id}>{option.text}</li>
          ))}
        </ul>
        <div>
          <label htmlFor="newOption">New Option:</label>
          <input
            type="text"
            id="newOption"
            value={newOptionText}
            onChange={(e) => setNewOptionText(e.target.value)}
            required
          />
          <button type="button" onClick={handleAddOption}>Add Option</button>
        </div>
      </div>
      <button type="submit">Create Poll</button>
    </form>
  );
}

