import React, { FC, useState } from "react";

interface Member {
  id: number;
  name: string;
}

export function CheckInScanner(): JSX.Element {
  const [memberCode, setMemberCode] = useState<string>("");
  const [member, setMember] = useState<Member | null>(null);

  const handleScan = async (): Promise<void> => {
    try {
      const response = await fetch(`/api/billing-service/members/${Number(memberCode)}`);
      if (!response.ok) {
        throw new Error("Member not found");
      }
      const data = await response.json();
      setMember(data);
    } catch (error) {
      console.error(error);
      alert("Member not found");
    }
  };

  const handleCheckIn = async (): Promise<void> => {
    if (!member) {
      alert("Please scan a valid member code first.");
      return;
    }

    try {
      await fetch(`/api/check-in-api/check-in`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ memberId: member.id }),
      });
      alert(`${member.name} has been checked in.`);
    } catch (error) {
      console.error(error);
      alert("Failed to check in member.");
    }
  };

  return (
    <div>
      <input
        type="text"
        value={memberCode}
        onChange={(e) => setMemberCode(e.target.value)}
        placeholder="Enter member code"
      />
      <button onClick={handleScan}>Scan</button>
      {member && (
        <div>
          <p>{`${member.name} (${member.id})`}</p>
          <button onClick={handleCheckIn}>Check In</button>
        </div>
      )}
    </div>
  );
}

