    event.preventDefault();
    if (!formData.receiptFile || !formData.amount || !formData.category) {
      alert("Please fill out all fields.");
      return;
    }

    const formDataObj = new FormData();
    formDataObj.append("receipt", formData.receiptFile);
    formDataObj.append("amount", formData.amount);
    formDataObj.append("category", formData.category);

    try {
      const response = await fetch("/api/expenses-api/", {
        method: "POST",
        body: formDataObj,
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      alert("Expense submitted successfully!");
    } catch (error) {
      console.error("Error submitting expense:", error);
      alert("Failed to submit expense.");
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <div>
        <label htmlFor="receipt">Upload Receipt:</label>
        <input type="file" id="receipt" onChange={handleReceiptChange} required />
      </div>
      <div>
        <label htmlFor="amount">Amount:</label>
        <input type="text" id="amount" value={formData.amount} onChange={handleAmountChange} required />
      </div>
      <div>
        <label htmlFor="category">Category:</label>
        <select id="category" value={formData.category} onChange={handleCategoryChange} required>
          <option value="">--Please choose a category--</option>
          <option value="travel">Travel</option>
          <option value="food">Food</option>
          <option value="supplies">Supplies</option>
        </select>
      </div>
      <button type="submit">Submit Expense</button>
    </form>
  );
}

