import { DatabaseSync } from "node:sqlite";

export interface Shift {
  id: number;
  description: string;
  startTime: string;
  endTime: string;
  capacity: number;
}

export const db = new DatabaseSync(":memory:");
db.exec(`
  CREATE TABLE IF NOT EXISTS shifts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    description TEXT NOT NULL,
    start_time DATETIME NOT NULL,
    end_time DATETIME NOT NULL,
    capacity INTEGER NOT NULL
  );
`);

export function insertShift(description: string, startTime: string, endTime: string, capacity: number): void {
  const stmt = db.prepare(`INSERT INTO shifts (description, start_time, end_time, capacity) VALUES (?, ?, ?, ?)`);
  stmt.run(description, startTime, endTime, capacity);
}

export function getShiftById(id: number): Shift | undefined {
  const stmt = db.prepare(`SELECT * FROM shifts WHERE id = ?`);
  const result = stmt.get(id) as unknown as Shift;
  return result;
}

export function getAllShifts(): Shift[] {
  const stmt = db.prepare(`SELECT * FROM shifts`);
  const results = stmt.all() as unknown as Shift[];
  return results;
}

