import React, { FC, useState } from "react";

interface ShiftEvent {
  type: "start" | "end";
  timestamp: number;
}

export function ClockInOutWidget(): JSX.Element {
  const [shiftEventType, setShiftEventType] = useState<"start" | "end">("start");

  const handleClockInOrOut = async () => {
    const event: ShiftEvent = {
      type: shiftEventType,
      timestamp: Date.now(),
    };

    try {
      await fetch("/api/timesheets-api/events", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(event),
      });
      alert(`${event.type.toUpperCase()} recorded successfully!`);
    } catch (error) {
      console.error(`Failed to record ${event.type}:`, error);
      alert(`Failed to record ${event.type}. Please try again.`);
    }
  };

  return (
    <div>
      <button onClick={() => setShiftEventType("start")}>Clock In</button>
      <button onClick={() => setShiftEventType("end")}>Clock Out</button>
      <button onClick={handleClockInOrOut}>{shiftEventType === "start" ? "Start Shift" : "End Shift"}</button>
    </div>
  );
}

