import React, { FC, useEffect, useState } from "react";

interface Spot {
  id: number;
  status: string;
}

export function SpotReservationView(): JSX.Element {
  const [spots, setSpots] = useState<Spot[]>([]);

  useEffect(() => {
    fetch("/api/parking-api/reservations")
      .then(response => response.json())
      .then(data => setSpots(data));
  }, []);

  const handleReserveSpot = (spotId: number) => {
    fetch(`/api/parking-api/reservations/${spotId}`, { method: "POST" })
      .then(response => response.json())
      .then(updatedSpot => {
        setSpots(prevSpots => prevSpots.map(spot => spot.id === updatedSpot.id ? updatedSpot : spot));
      });
  };

  return (
    <div>
      <h1>Today's Parking Spots</h1>
      <ul>
        {spots.map(spot => (
          <li key={spot.id} style={{ textDecoration: spot.status === "reserved" ? "line-through" : "none" }}>
            Spot {spot.id}: {spot.status}
            {spot.status !== "reserved" && (<button onClick={() => handleReserveSpot(spot.id)}>Reserve</button>)}
          </li>
        ))}
      </ul>
    </div>
  );
}
